      "text": "// ───────────────────────────────────────────────────────────────────────────── function OC_DispatchDetail({ theme: th, domain = 'owned' }) { const o = domain === 'owned' ? FX_DISPATCH_OWNED[2] : FX_DISPATCH_FORWARDED[2]; const wid = domain === 'owned' ? o.id : o.id; return ( <Shell theme={th} nav={OPS_NAV} active=\"dispatch\" breadcrumb={['派車調度', wid]} env=\"production\" actor={OPS_ACTOR} health={OPS_HEALTH} refreshTier=\"dispatch\" dataFreshness=\"fresh\"> <PageHeader theme={th} title={ <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10 }}> <span>{wid}</span> <Pill theme={th} tone={domain === 'forwarded' ? 'info' : 'accent'}>{domain === 'forwarded' ? 'FORWARDED' : 'OWNED'}</Pill> </span> } subtitle={ domain === 'owned' ? `${o.tenant} · ${o.pickup} → ${o.drop} · ${o.win}` : `${o.source} · ${o.external} · ${o.pickup} → ${o.drop} · ${o.win}` } actions={<> <ActionButton theme={th} descriptor={{ action: 'phone', enabled: true, riskLevel: 'low' }} icon=\"phone\" label=\"聯絡乘客\" en=\"call\" /> <ActionButton theme={th} descriptor={{ action: 'fare_override', enabled: true, riskLevel: 'high', requiresReason: true }} icon=\"warn\" label=\"fare override\" en=\"request\" /> <ActionButton theme={th} descriptor={{ action: 'assign', enabled: true, riskLevel: 'medium' }} icon=\"check\" label=\"指派候選 #1\" en=\"assign\" /> </>} /> <div style={{ padding: 24, display: 'grid', gridTemplateColumns: '1.4fr 1fr', gap: 16 }}> <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}> {domain === 'forwarded' && ( <Banner theme={th} tone=\"info\" icon=\"info\" title=\"此訂單為 forwarded mirror · 不可假裝為 owned\" body=\"所有 mutation 必須透過 reconciliation issue 走平台 finance owner。本地僅 sync external state。\" /> )} <Card theme={th} title=\"候選 driver · ranked (3)\"> <Table theme={th} columns={[ { h: '#', w: 36, r: (_, i) => <span style={{ fontWeight: 700, color: th.accent, fontFamily: SHELL_MONO }}>{i + 1}</span> }, { h: 'DRIVER', w: 160, r: r => (<div><div style={{ fontWeight: 600 }}>{r.name}</div><div style={{ fontSize: 11, color: th.textDim, fontFamily: SHELL_MONO }}>{r.id}</div></div>) }, { h: 'VEHICLE', k: 'vehicle', w: 130, mono: true }, { h: 'ETA', w: 80, r: () => <Pill theme={th} tone=\"success\">8m</Pill> }, { h: 'GATE', w: 180, r: (_, i) => i === 1 ? <Pill theme={th} tone=\"warn\" dot>license_expiring</Pill> : <Pill theme={th} tone=\"success\">ok</Pill> }, { h: 'SCORE', w: 70, r: (_, i) => <span style={{ fontFamily: SHELL_MONO }}>{[0.94, 0.87, 0.82][i] || '—'}</span> }, ]} rows={FX_DRIVERS.slice(2, 5)} /> </Card> <Card theme={th} title=\"Compliance gates · authority chain\"> <DL theme={th} cols={2} items={[ { k: 'license valid', v: <Pill theme={th} tone=\"warn\">2 / 3 候選通過</Pill> }, { k: 'service bucket', v: 'business · ok', mono: true }, { k: 'exclusivity', v: 'ok', mono: true }, { k: 'device binding', v: '3 / 3 ok', mono: true }, { k: 'fare quoted', v: 'NT$ 3,420 · pr_v23', mono: true }, { k: 'override allowed', v: 'reviewer required', mono: true }, ]} /> </Card> </div> <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}> <Card theme={th} title=\"State machine\"> <Stepper theme={th} steps={[{ t: '建立' }, { t: 'queued' }, { t: 'broadcasting' }, { t: 'assigned' }, { t: 'on_trip' }, { t: 'completed' }]} current={domain === 'owned' ? 1 : 2} /> </Card> <Card theme={th} title=\"活動 · Timeline\"> <Timeline theme={th} events={[ { at: '15:42', tone: 'accent', t: '進入 queue', actor: 'tenant.api', actorRealm: 'tenant', body: 'CATHAY_LIFE 透過 API 建立。' }, { at: '15:43', tone: 'accent', t: '計價', actor: 'pricing.engine', actorRealm: 'system', body: '套用 pr_v23 商務規則：NT$ 3,420。' }, { at: '15:45', tone: 'warn', t: 'gate warning', actor: 'compliance', actorRealm: 'system', body: '候選 #2 license 距到期 < 30 天，已標記。' }, { at: '15:46', tone: 'accent', t: '評估', actor: 'dispatch.scorer', actorRealm: 'system', body: '3 名候選，最高 0.94。' }, ]} /> </Card> </div> </div> </Shell> ); }",
